import {N,SHAPES,rotate,fits,clearLines,hasMoves,blast,HARD_SHAPES,pressureStep,injectGarbage} from './engine.mjs';
const $=id=>document.getElementById(id),colors=['#00f5e9','#fa42c6','#ffcf39','#8d69ff','#f05a44'];let state,selected=0,hover=null,armed=false,previous=null,sound=false,ac,toastTimer;let best=0;let effects=!matchMedia("(prefers-reduced-motion: reduce)").matches,cinemaTimer;
try{best=Number(localStorage.getItem('flux-best'))||0}catch{}
function piece(){const level=1+Math.floor((state?.lines||0)/5),pool=level>=4?[...SHAPES.slice(3),...HARD_SHAPES]:level>=2?[...SHAPES.slice(2),...HARD_SHAPES.slice(0,5)]:SHAPES.slice(2);return {shape:structuredClone(pool[Math.floor(Math.random()*pool.length)]),color:1+Math.floor(Math.random()*4)}}
function fresh(){state=undefined;state={board:Array(64).fill(0),pieces:[piece(),piece(),piece()],score:0,energy:20,lines:0,combo:0,moves:0,mission:1,pressure:0};selected=0;previous=null;armed=false;hover=null;injectGarbage(state.board,5);render();cinematic('SYSTEM ONLINE','STAGE 01','BASKIYI YÖNET · REKORU KIR')}
function save(){try{localStorage.setItem('flux-save-v1',JSON.stringify(state));localStorage.setItem('flux-best',String(best))}catch{}}
function load(){try{const s=JSON.parse(localStorage.getItem('flux-save-v1'));if(s&&s.board?.length===64&&s.board.every(v=>Number.isInteger(v)&&v>=0&&v<=5)&&s.pieces?.length===3&&s.pieces.every(p=>p===null||(p.shape?.length>0&&p.shape.every(v=>v.length===2&&v.every(Number.isInteger))&&p.color>=1&&p.color<=4))&&['score','energy','lines','combo','moves','mission'].every(k=>Number.isFinite(s[k])&&s[k]>=0)&&s.mission>=1){state=s;state.pressure=Number.isFinite(s.pressure)?s.pressure:0;selected=s.pieces.findIndex(Boolean);render();return}}catch{}fresh()}
function beep(clear=false){if(!sound)return;try{ac??=new (window.AudioContext||window.webkitAudioContext)();ac.resume();let o=ac.createOscillator(),g=ac.createGain();o.type='square';o.frequency.setValueAtTime(clear?660:260,ac.currentTime);o.frequency.exponentialRampToValueAtTime(clear?990:390,ac.currentTime+.12);g.gain.setValueAtTime(.07,ac.currentTime);g.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.2);o.connect(g);g.connect(ac.destination);o.start();o.stop(ac.currentTime+.2)}catch{}}
function toast(t){$('float-message').textContent=t;$('float-message').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('float-message').classList.remove('show'),1400)}
function cinematic(k,t,sub){if(!effects){toast(t);return}$('cinema-kicker').textContent=k;$('cinema-title').textContent=t;$('cinema-sub').textContent=sub;$('cinema').classList.remove('active');void $('cinema').offsetWidth;$('cinema').classList.add('active');clearTimeout(cinemaTimer);cinemaTimer=setTimeout(()=>$('cinema').classList.remove('active'),1600)}
function burst(indices,color='#00f5e9'){if(!effects)return;indices.slice(0,16).forEach(i=>{const r=cells[i].getBoundingClientRect();for(let j=0;j<3;j++){const p=document.createElement('i');p.className='spark';p.style.left=r.left+r.width/2+'px';p.style.top=r.top+r.height/2+'px';p.style.background=color;p.style.setProperty('--dx',(Math.random()-.5)*210+'px');p.style.setProperty('--dy',(Math.random()-.65)*220+'px');$('fx-layer').append(p);setTimeout(()=>p.remove(),900)}});const wrap=document.querySelector('.board-wrap');wrap.classList.remove('shake');void wrap.offsetWidth;wrap.classList.add('shake')}
const cells=Array.from({length:64},(_,i)=>{let b=document.createElement('button');b.className='cell';b.setAttribute('role','gridcell');b.tabIndex=-1;b.setAttribute('aria-label',`${Math.floor(i/8)+1}. satır, ${i%8+1}. sütun`);b.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'){hover=[i%8,Math.floor(i/8)];paint()}});b.addEventListener('click',()=>{hover=[i%8,Math.floor(i/8)];place(...hover)});$('board').appendChild(b);return b});
$('board').addEventListener('pointerleave',()=>{hover=null;paint()});
function paint(){cells.forEach((b,i)=>{b.className='cell'+(state.board[i]?' filled':'')+(state.board[i]===5?' garbage':'');b.style.setProperty('--block',colors[state.board[i]-1]||'transparent');b.setAttribute('aria-label',`${Math.floor(i/8)+1}. satır, ${i%8+1}. sütun, ${state.board[i]?'dolu':'boş'}`)});if(!hover)return;let [x,y]=hover;if(armed){for(let dy=-1;dy<=1;dy++)for(let dx=-1;dx<=1;dx++)if(x+dx>=0&&x+dx<8&&y+dy>=0&&y+dy<8)cells[(y+dy)*8+x+dx].classList.add('invalid');return}const p=state.pieces[selected];if(!p)return;const ok=fits(state.board,p.shape,x,y);p.shape.forEach(([dx,dy])=>{if(x+dx<8&&y+dy<8&&x+dx>=0&&y+dy>=0)cells[(y+dy)*8+x+dx].classList.add(ok?'ghost':'invalid')});}
function select(i){if(!state.pieces[i])return;selected=i;armed=false;render()}
function render(){$('pressure-value').textContent=state.pressure+'%';$('pressure-bar').style.width=state.pressure+'%';document.body.classList.toggle('danger',state.pressure>=70);$('pressure-hint').textContent=state.pressure>=70?'KRİTİK: çizgi temizle veya saldırıya hazırlan!':'%100 baskı = yeni parazitler. Çizgi temizle, soğut.';best=Math.max(best,state.score);$('score').textContent=state.score.toLocaleString('tr-TR');$('best').textContent=best.toLocaleString('tr-TR');$('lines').textContent=state.lines;$('level').textContent=String(1+Math.floor(state.lines/5)).padStart(2,'0');$('energy').textContent=state.energy;$('energy-bar').style.width=state.energy+'%';$('mission-title').textContent=`${state.mission*5} çizgi temizle`;$('mission-count').textContent=`${state.lines}/${state.mission*5}`;$('mission-bar').style.width=Math.min(100,state.lines/(state.mission*5)*100)+'%';$('combo').textContent=state.combo>1?`×${state.combo} KOMBO`:'READY PLAYER ONE';$('combo').style.color=state.combo>1?'var(--lime)':'';$('status').textContent=armed?'Darbe için bir kare seç':'Sıra sende';$('blast').disabled=state.energy<75;$('blast').classList.toggle('active',armed);$('energy-note').textContent=armed?'İptal etmek için Darbe’ye tekrar dokun':state.energy>=75?'Darbe hazır. Doğru anı bekle.':'Yetenek için enerji biriktir';$('undo').disabled=!previous;$('rotate').disabled=!state.pieces[selected]||armed;$('tray').replaceChildren();state.pieces.forEach((p,i)=>{const b=document.createElement('button');b.className='piece'+(i===selected&&!armed?' selected':'');b.setAttribute('aria-label',`${i+1}. blok${p?', '+p.shape.length+' kare':', kullanıldı'}`);b.setAttribute('aria-pressed',String(i===selected&&!armed));b.disabled=!p;b.innerHTML=`<span class="num">0${i+1}</span>`;if(p){const mini=document.createElement('div');mini.className='mini';let w=Math.max(...p.shape.map(a=>a[0]))+1,h=Math.max(...p.shape.map(a=>a[1]))+1;mini.style.gridTemplateColumns=`repeat(${w},20px)`;for(let y=0;y<h;y++)for(let x=0;x<w;x++){let c=document.createElement('span');c.className='mini-cell'+(p.shape.some(a=>a[0]===x&&a[1]===y)?'':' empty');c.style.setProperty('--block',colors[p.color-1]);mini.append(c)}b.append(mini);b.onclick=()=>select(i)}else b.innerHTML+='<span class="used">✓</span>';$('tray').append(b)});const stuck=!hasMoves(state.board,state.pieces);$('end').classList.toggle('hidden',!stuck||state.energy>=75);$('end-score').textContent=`${state.score.toLocaleString('tr-TR')} puan · ${state.lines} çizgi`;if(stuck&&state.energy>=75)$('status').textContent='Darbe ile yer açabilirsin';paint();save()}
function place(x,y){if(!$('end').classList.contains('hidden'))return;if(armed){if(state.energy<75)return;let b=state.board.slice(),n=blast(b,x,y);const blasted=state.board.map((v,i)=>v&&!b[i]?i:-1).filter(i=>i>=0);if(!n){toast('Dolu bir alan seç');return}previous=structuredClone(state);state.board=b;state.energy-=75;state.score+=n*5;armed=false;hover=null;beep(true);render();burst(blasted,'#fa42c6');cinematic('FLUX WEAPON ONLINE','PULSE BREAK','3 × 3 ALAN TEMİZLENDİ');return}const p=state.pieces[selected];if(!p)return;if(!fits(state.board,p.shape,x,y)){toast('Bu blok buraya sığmıyor');return}previous=structuredClone(state);p.shape.forEach(([dx,dy])=>state.board[(y+dy)*8+x+dx]=p.color);state.score+=p.shape.length*10;state.moves++;let result=clearLines(state.board);state.combo=result.count?state.combo+1:0;state.lines+=result.count;let bonus=result.count*100*Math.max(1,result.count)*Math.max(1,state.combo);state.score+=bonus;state.energy=Math.min(100,state.energy+result.count*15);state.pressure=pressureStep(state.pressure,result.count,1+Math.floor(state.lines/5));let garbage=[];if(state.pressure>=100){state.pressure=0;garbage=injectGarbage(state.board,3+Math.min(4,Math.floor(state.lines/5)))}let mission=false;while(state.lines>=state.mission*5){state.score+=250;state.mission++;mission=true}state.pieces[selected]=null;if(state.pieces.every(p=>!p))state.pieces=[piece(),piece(),piece()];selected=state.pieces.findIndex(Boolean);hover=null;render();result.cells.forEach(i=>cells[i].classList.add('flash'));beep(result.count>0);if(garbage.length){burst(garbage,'#ff6348');cinematic('WARNING // OVERLOAD','PARAZİT SALDIRISI',garbage.length+' YENİ BLOK · TEMİZLE VE KURTUL')}else if(mission){burst(result.cells);cinematic('SECTOR COMPLETE +250','STAGE '+String(1+Math.floor(state.lines/5)).padStart(2,'0'),'BASKI YÜKSELİYOR')}else if(result.count){burst(result.cells);if(state.combo>1||result.count>1)cinematic('CHAIN REACTION',state.combo>1?'COMBO ×'+state.combo:'MULTI BREAK','+'+bonus+' PUAN');else toast('LINE BREAK +'+bonus)}}
$('rotate').onclick=()=>{if(!state.pieces[selected]||armed)return;state.pieces[selected].shape=rotate(state.pieces[selected].shape);render()};$('undo').onclick=()=>{if(!previous)return;state=previous;previous=null;selected=state.pieces.findIndex(Boolean);hover=null;armed=false;render();toast('Hamle geri alındı')};$('blast').onclick=()=>{if(state.energy>=75){armed=!armed;render()}};$('help').onclick=()=>$('dialog').showModal();document.querySelector('.close').onclick=()=>$('dialog').close();document.querySelector('.close-start').onclick=()=>$('dialog').close();$('restart').onclick=()=>$('confirm').showModal();$('cancel').onclick=()=>$('confirm').close();$('confirm-new').onclick=()=>{$('confirm').close();fresh()};$('again').onclick=fresh;$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♫':'♪';$('sound').setAttribute('aria-label',sound?'Sesi kapat':'Sesi aç');$('sound').style.color=sound?'var(--lime)':'';beep()};
document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey)return;let k=e.key.toLowerCase();if(['1','2','3'].includes(k)){e.preventDefault();select(+k-1)}else if(k==='r')$('rotate').click();else if(k==='z')$('undo').click();else if(k==='escape'){armed=false;render()}else if(k.startsWith('arrow')){e.preventDefault();hover??=[0,0];let [x,y]=hover;if(k==='arrowleft')x--;if(k==='arrowright')x++;if(k==='arrowup')y--;if(k==='arrowdown')y++;hover=[Math.max(0,Math.min(7,x)),Math.max(0,Math.min(7,y))];$('board').focus();paint()}else if((k==='enter'||k===' ')&&document.activeElement===$('board')){e.preventDefault();hover??=[0,0];place(...hover)}});$('effects').onclick=()=>{effects=!effects;document.body.classList.toggle('low-fx',!effects);$('effects').setAttribute('aria-label',effects?'Efektleri azalt':'Efektleri aç');if(!effects){$('cinema').classList.remove('active');$('fx-layer').replaceChildren()}};document.body.classList.toggle('low-fx',!effects);load();$('start-screen').showModal();$('start-play').onclick=()=>{$('start-screen').close();cinematic('SYSTEM ONLINE','LET’S PLAY','HER HAMLE BİR KARAR')};
